//! Fault/mutation corpus for the general instrument, not goldens generated by the UI.
use super::*;
use config::{Animation, Bounds, Budget, Exclusion, ExclusionKind, Region};
use image::{Rgba, RgbaImage};
use serde_json::{Value, json};

fn policy(hash: &str) -> Value {
    json!({
        "schema":1,"scenario":"independent-game-panel","fixture":"fixed-seed-1",
        "profile":{"id":"test","platform":"fixture","renderer":"software-fixture",
            "environment":"deterministic-test","logical_size":[20,12],"dpr":1,
            "color_space":"srgb_assumed","motion":"normal"},
        "reference":{"image":"reference.png","sha256":hash,"source":"independent test fixture",
            "kind":"regression_golden","approval":"pending","export_size":[20,12],
            "crop":[0,0,20,12],"crop_reason":"complete client frame"},
        "animation":{"mode":"static"},
        "comparison":{"normalized_yiq_tolerance":0,"budget":{"max_changed_pixels":0,"max_changed_ppm":0},
            "max_excluded_ppm":100_000,"allow_uniform_reason":null},
        "exclusions":[],"critical_regions":[]
    })
}

#[test]
fn reviewed_variance_preserves_unmasked_critical_pixels_caps_and_original_evidence()
-> crate::Result<()> {
    let mut fixture = Fixture::new()?;
    let mut raw = policy(&fixture.config.reference.sha256);
    raw["exclusions"] = json!([{"name":"approved glyph interior",
        "reason":"Owner accepts font rasterization here, not the surrounding control edge",
        "kind":"approved_visual_variance","rect":[5,5,1,1]}]);
    raw["critical_regions"] = json!([{"name":"control","rect":[4,4,4,4],
        "budget":{"max_changed_pixels":0,"max_changed_ppm":0}}]);
    let pending: Config = serde_json::from_value(raw.clone())?;
    assert!(pending.validate().is_err());
    raw["reference"]["approval"] = json!("human_reviewed");
    fixture.config = serde_json::from_value(raw.clone())?;
    fixture.config.validate()?;
    let mut actual = image();
    actual.put_pixel(5, 5, Rgba([90, 90, 90, 255]));
    actual.save(fixture.root.path().join("actual.png"))?;
    fixture.write()?;
    fixture.verify("accepted")?;
    let accepted = fixture.result("accepted")?;
    assert_eq!(accepted["domains"][1]["excluded_pixels"], 1);
    assert_eq!(accepted["domains"][1]["eligible_pixels"], 15);
    assert_eq!(
        image::open(fixture.root.path().join("accepted/actual-source.png"))?.to_rgba8(),
        actual
    );
    actual.put_pixel(4, 4, Rgba([255, 0, 0, 255]));
    actual.save(fixture.root.path().join("actual.png"))?;
    fixture.write()?;
    assert!(fixture.verify("broken-edge").is_err());
    assert_eq!(
        fixture.result("broken-edge")?["domains"][1]["matched"],
        false
    );
    raw["comparison"]["max_excluded_ppm"] = json!(0);
    fixture.config = serde_json::from_value(raw.clone())?;
    fixture.write()?;
    assert!(fixture.verify("over-cap").is_err());
    raw["comparison"]["max_excluded_ppm"] = json!(100_000);
    raw["exclusions"][0]["rect"] = json!([4, 4, 4, 4]);
    fixture.config = serde_json::from_value(raw.clone())?;
    fixture.write()?;
    assert!(fixture.verify("erased-critical-domain").is_err());
    raw["exclusions"][0]["kind"] = json!("volatile_data");
    let volatile: Config = serde_json::from_value(raw)?;
    assert!(
        volatile.validate().is_err(),
        "Volatility still cannot mask critical regions"
    );
    Ok(())
}

fn image() -> RgbaImage {
    let mut image = RgbaImage::from_pixel(20, 12, Rgba([36, 36, 36, 255]));
    image.put_pixel(5, 5, Rgba([230, 230, 230, 255]));
    image
}

struct Fixture {
    root: tempfile::TempDir,
    config: Config,
}

impl Fixture {
    fn new() -> crate::Result<Self> {
        let root = tempfile::tempdir()?;
        image().save(root.path().join("reference.png"))?;
        image().save(root.path().join("actual.png"))?;
        let hash = images::digest(&fs::read(root.path().join("reference.png"))?);
        let config = serde_json::from_value(policy(&hash))?;
        let fixture = Self { root, config };
        fixture.write()?;
        Ok(fixture)
    }

    fn write(&self) -> crate::Result<()> {
        report::write_json(self.root.path().join("policy.json"), &self.config)?;
        report::write_json(
            self.root.path().join("capture.json"),
            &json!({
                "schema":1,"scenario":self.config.scenario,"fixture":self.config.fixture,
                "profile":self.config.profile,"image":"actual.png",
                "sha256":images::digest(&fs::read(self.root.path().join("actual.png"))?),
                "producer":"unit fixture","readiness":"deterministic pixels supplied by test",
                "receipt_frame":null
            }),
        )
    }

    fn verify(&self, directory: &str) -> crate::Result<()> {
        verify(
            &self.root.path().join("policy.json"),
            &self.root.path().join("capture.json"),
            &self.root.path().join(directory),
        )
    }

    fn result(&self, directory: &str) -> crate::Result<Value> {
        parse(&self.root.path().join(directory).join("report.json"))
    }
}

#[test]
fn identical_pixels_still_require_human_review_and_never_overwrite() -> crate::Result<()> {
    let fixture = Fixture::new()?;
    let before = fs::read(fixture.root.path().join("reference.png"))?;
    fixture.verify("review")?;
    let result = fixture.result("review")?;
    assert_eq!(result["automated_result"], "matched");
    assert_eq!(result["design_acceptance"], "awaiting_human_review");
    assert_eq!(result["domains"][0]["eligible_pixels"], 240);
    assert!(fixture.verify("review").is_err());
    assert_eq!(fs::read(fixture.root.path().join("reference.png"))?, before);
    assert_eq!(
        fs::read(fixture.root.path().join("review/actual-source.png"))?,
        fs::read(fixture.root.path().join("actual.png"))?
    );
    for file in [
        "index.html",
        "difference.png",
        "exact-difference.png",
        "exclusions.png",
        "overlay.png",
        "side-by-side.png",
        "policy.json",
        "capture.json",
    ] {
        assert!(
            fixture.root.path().join("review").join(file).is_file(),
            "{file}"
        );
    }
    Ok(())
}

#[test]
fn a_one_pixel_translation_fails_without_alignment() -> crate::Result<()> {
    let fixture = Fixture::new()?;
    let mut shifted = image();
    shifted.put_pixel(5, 5, Rgba([36, 36, 36, 255]));
    shifted.put_pixel(6, 5, Rgba([230, 230, 230, 255]));
    shifted.save(fixture.root.path().join("actual.png"))?;
    fixture.write()?;
    assert!(fixture.verify("shifted").is_err());
    let result = fixture.result("shifted")?;
    assert_eq!(result["automated_result"], "mismatch");
    assert_eq!(result["domains"][0]["perceptual_changed_pixels"], 2);
    Ok(())
}

#[test]
fn tolerant_policy_accepts_minor_shades_but_rejects_missing_local_content() -> crate::Result<()> {
    let mut fixture = Fixture::new()?;
    fixture.config.comparison.normalized_yiq_tolerance = 0.05;
    fixture.config.comparison.budget = Budget {
        max_changed_pixels: 4,
        max_changed_ppm: 20_000,
    };
    fixture.config.critical_regions.push(Region {
        name: "control-glyph".into(),
        rect: [4., 4., 4., 4.],
        budget: Budget {
            max_changed_pixels: 0,
            max_changed_ppm: 20_000,
        },
    });
    let mut shades = image();
    for pixel in shades.pixels_mut() {
        for channel in &mut pixel.0[..3] {
            *channel = channel.saturating_add(2);
        }
    }
    shades.save(fixture.root.path().join("actual.png"))?;
    fixture.write()?;
    fixture.verify("minor-shades")?;
    // One missing bright glyph pixel passes the whole-frame percentage but must
    // fail its local region; a broad page budget cannot certify small controls.
    shades.put_pixel(5, 5, Rgba([38, 38, 38, 255]));
    shades.put_pixel(15, 8, Rgba([230, 230, 230, 255]));
    shades.save(fixture.root.path().join("actual.png"))?;
    fixture.write()?;
    assert!(fixture.verify("missing-glyph").is_err());
    let result = fixture.result("missing-glyph")?;
    assert_eq!(result["domains"][0]["matched"], true);
    assert_eq!(result["domains"][1]["matched"], false);
    Ok(())
}

#[test]
fn union_masks_use_eligible_denominator_and_do_not_erase_diagnostics() -> crate::Result<()> {
    let mut fixture = Fixture::new()?;
    for name in ["first", "overlap"] {
        fixture.config.exclusions.push(Exclusion {
            name: name.into(),
            reason: "volatile data".into(),
            kind: ExclusionKind::VolatileData,
            rect: [0., 0., 2., 12.],
        });
    }
    fixture.config.comparison.max_excluded_ppm = 100_000;
    let mut actual = image();
    actual.put_pixel(0, 0, Rgba([255, 255, 255, 255]));
    actual.put_pixel(10, 0, Rgba([255, 255, 255, 255]));
    let compared = compare::compare(&fixture.config, &image(), &actual)?;
    assert_eq!(compared.domains[0].excluded_pixels, 24);
    assert_eq!(compared.domains[0].eligible_pixels, 216);
    assert_eq!(compared.domains[0].perceptual_changed_pixels, 1);
    assert_eq!(compared.domains[0].exact_changed_pixels, 1);
    assert_eq!(compared.exact_difference.get_pixel(0, 0)[0], 255);
    assert_eq!(actual.get_pixel(0, 0)[0], 255);
    fixture.config.comparison.max_excluded_ppm = 99_999;
    assert!(compare::compare(&fixture.config, &image(), &actual).is_err());
    Ok(())
}

#[test]
fn both_budgets_must_pass_using_integer_unrounded_ratios() {
    let budget = Budget {
        max_changed_pixels: 2,
        max_changed_ppm: 100_000,
    };
    assert!(budget.passes(2, 20));
    assert!(!budget.passes(2, 19));
    assert!(!budget.passes(3, 1000));
    assert!(!budget.passes(0, 0));
}

#[test]
fn critical_control_fails_even_when_global_budget_passes() -> crate::Result<()> {
    let mut fixture = Fixture::new()?;
    fixture.config.comparison.budget = Budget {
        max_changed_pixels: 240,
        max_changed_ppm: 1_000_000,
    };
    fixture.config.critical_regions.push(Region {
        name: "close-control".into(),
        rect: [5., 5., 1., 1.],
        budget: Budget {
            max_changed_pixels: 0,
            max_changed_ppm: 0,
        },
    });
    let mut actual = image();
    actual.put_pixel(5, 5, Rgba([36, 36, 36, 255]));
    let compared = compare::compare(&fixture.config, &image(), &actual)?;
    assert!(compared.domains[0].matched);
    assert!(!compared.domains[1].matched);
    fixture.config.exclusions.push(Exclusion {
        name: "hide-control".into(),
        reason: "not permitted".into(),
        rect: [5., 5., 1., 1.],
        kind: ExclusionKind::VolatileData,
    });
    assert!(fixture.config.validate().is_err());
    Ok(())
}

#[test]
fn rect_resolution_rounds_outward_and_rejects_invalid_geometry() -> crate::Result<()> {
    let mut fixture = Fixture::new()?;
    fixture.config.profile.dpr = 1.5;
    let bounds = fixture.config.profile.resolve([0.1, 0.1, 1., 1.])?;
    assert!(matches!(bounds, Bounds(0, 0, 2, 2)));
    for rect in [
        [-1., 0., 1., 1.],
        [0., 0., 0., 1.],
        [19.5, 0., 1., 1.],
        [f64::NAN, 0., 1., 1.],
    ] {
        assert!(fixture.config.profile.resolve(rect).is_err());
    }
    fixture.config.profile.logical_size = [1, 1];
    assert!(fixture.config.profile.physical_size().is_err());
    Ok(())
}

#[test]
fn malformed_configuration_and_unsupported_animation_never_fallback() -> crate::Result<()> {
    let mut fixture = Fixture::new()?;
    let mut value = policy(&fixture.config.reference.sha256);
    value["typo"] = json!(1);
    assert!(serde_json::from_value::<Config>(value).is_err());
    assert!(serde_json::from_str::<Config>(r#"{"schema":1,"schema":1}"#).is_err());
    fixture.config.comparison.normalized_yiq_tolerance = f32::NAN;
    assert!(fixture.config.validate().is_err());
    fixture.config.comparison.normalized_yiq_tolerance = 0.;
    fixture.config.animation = Animation::Keyframes;
    fixture.write()?;
    assert!(fixture.verify("unsupported").is_err());
    assert_eq!(
        fixture.result("unsupported")?["automated_result"],
        "unsupported"
    );
    fixture.config.animation = Animation::ExcludedInteriors;
    assert!(fixture.config.validate().is_err());
    Ok(())
}

#[test]
fn invalid_and_substituted_captures_fail_before_masks_or_tolerances() -> crate::Result<()> {
    for (name, actual) in [
        ("transparent", RgbaImage::new(20, 12)),
        (
            "uniform",
            RgbaImage::from_pixel(20, 12, Rgba([36, 36, 36, 255])),
        ),
        (
            "density",
            RgbaImage::from_pixel(40, 24, Rgba([36, 36, 36, 255])),
        ),
    ] {
        let fixture = Fixture::new()?;
        actual.save(fixture.root.path().join("actual.png"))?;
        fixture.write()?;
        assert!(fixture.verify(name).is_err());
        assert_eq!(fixture.result(name)?["automated_result"], "invalid_capture");
        assert!(
            fixture
                .root
                .path()
                .join(name)
                .join("actual-source.png")
                .is_file()
        );
    }
    let fixture = Fixture::new()?;
    fs::write(fixture.root.path().join("actual.png"), b"not a PNG")?;
    assert!(fixture.verify("substituted").is_err());
    fixture.write()?;
    assert!(fixture.verify("corrupt").is_err());
    Ok(())
}

#[test]
fn missing_or_replaced_reference_and_wrong_profile_are_distinct_failures() -> crate::Result<()> {
    let fixture = Fixture::new()?;
    fs::remove_file(fixture.root.path().join("reference.png"))?;
    assert!(fixture.verify("missing").is_err());
    assert_eq!(
        fixture.result("missing")?["automated_result"],
        "missing_reference"
    );
    assert!(
        fixture
            .root
            .path()
            .join("missing/actual-source.png")
            .is_file()
    );
    fs::write(fixture.root.path().join("reference.png"), b"replaced")?;
    assert!(fixture.verify("replaced").is_err());
    assert_eq!(
        fixture.result("replaced")?["automated_result"],
        "invalid_reference"
    );
    let path = fixture.root.path().join("capture.json");
    let mut evidence: Value = parse(&path)?;
    evidence["profile"]["renderer"] = json!("another-backend");
    report::write_json(path, &evidence)?;
    assert!(fixture.verify("profile").is_err());
    assert_eq!(
        fixture.result("profile")?["automated_result"],
        "invalid_capture"
    );
    Ok(())
}

#[test]
fn normalized_yiq_adapter_has_known_boundaries_and_region_equivalence() -> crate::Result<()> {
    assert_eq!(compare::threshold(0.), 0.);
    assert_eq!(compare::threshold(1.), 35215.);
    let mut fixture = Fixture::new()?;
    let mut actual = image();
    actual.put_pixel(5, 5, Rgba([0, 0, 0, 255]));
    fixture.config.critical_regions.push(Region {
        name: "glyph".into(),
        rect: [4., 4., 3., 3.],
        budget: Budget {
            max_changed_pixels: 0,
            max_changed_ppm: 0,
        },
    });
    let strict = compare::compare(&fixture.config, &image(), &actual)?;
    assert_eq!(strict.domains[0].perceptual_changed_pixels, 1);
    assert_eq!(strict.domains[1].perceptual_changed_pixels, 1);
    fixture.config.comparison.normalized_yiq_tolerance = 1.;
    assert!(
        compare::compare(&fixture.config, &image(), &actual)?
            .domains
            .iter()
            .all(|d| d.matched)
    );
    Ok(())
}

#[test]
fn pinned_startup_layouts_validate_and_preserve_independent_exports() -> crate::Result<()> {
    let directory = Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/ui/references");
    for name in [
        "loading-locked-visual.json",
        "manager-empty-visual.json",
        "manager-visual.json",
        "create-visual.json",
        "open-visual.json",
        "boot-visual.json",
        "failure-visual.json",
        "create-invalid-visual.json",
        "open-invalid-visual.json",
    ] {
        let path = directory.join(name);
        let config: Config = parse(&path)?;
        config.validate()?;
        let bytes = images::read_bounded(
            &images::resolve_image(&path, &config.reference.image)?,
            images::MAX_FILE_BYTES,
        )?;
        assert_eq!(images::digest(&bytes), config.reference.sha256, "{name}");
        let export = images::decode(&bytes, config.reference.export_size)?;
        let [x, y, width, height] = config.reference.crop;
        let client = image::imageops::crop_imm(&export, x, y, width, height).to_image();
        images::validate_content(&client, false)?;
        assert!(
            config.exclusions.is_empty(),
            "{name}: changes to scope require review"
        );
    }
    Ok(())
}
